public static boolean onDamageSourceBlocking(LivingEntity blocker, ItemStack useItem, DamageSource source,
												 CallbackInfoReturnable<Boolean> info) {
		if (blocker instanceof Player player && useItem != null) {
			boolean blocking = ((IProperShieldUser)blocker).isActuallyReallyBlocking();

			if (!blocking)
				return false;

			if (useItem.getItem() instanceof InfernalShield) {
				boolean piercingArrow = false;
				Entity entity = source.getDirectEntity();

				if (entity instanceof AbstractArrow arrow) {
					if (arrow.getPierceLevel() > 0) {
						piercingArrow = true;
					}
				}

				piercingArrow = false; // defend against Piercing... for now

				if (!source.is(DamageTypeTags.BYPASSES_SHIELD) && !piercingArrow) {
					Vec3 sourcePos = source.getSourcePosition();

					if (sourcePos != null) {
						Vec3 lookVec = blocker.getViewVector(1.0F);
						Vec3 sourceToSelf = sourcePos.vectorTo(blocker.position()).normalize();
						sourceToSelf = new Vec3(sourceToSelf.x, 0.0D, sourceToSelf.z);

						if (sourceToSelf.dot(lookVec) < 0.0D) {
							int strength = -1;

							if (player.hasEffect(EnigmaticEffects.BLAZING_STRENGTH)) {
								MobEffectInstance effectInstance = player.getEffect(EnigmaticEffects.BLAZING_STRENGTH);
								strength = effectInstance.getAmplifier();
								player.removeEffect(EnigmaticEffects.BLAZING_STRENGTH);
								strength = strength > 2 ? 2 : strength;
							}

							player.addEffect(new MobEffectInstance(EnigmaticEffects.BLAZING_STRENGTH, 1200, strength + 1, true, true));

							if (source.getDirectEntity() instanceof LivingEntity living && living.isAlive()) {
								if (!living.fireImmune() && !(living instanceof Guardian)) {
									StackTraceElement[] stacktrace = Thread.currentThread().getStackTrace();

									// Ensure that we will not be caught in any sort of StackOverflow because of thorns-like effects
									if (Arrays.stream(stacktrace).filter(element -> {
										return SuperpositionHandler.class.getName().equals(element.getClassName());
									}).count() < 2) {
										living.invulnerableTime = 0;
										living.hurt(living.damageSources().source(DamageTypes.ON_FIRE, player), 4F);
										living.setSecondsOnFire(4);
										EnigmaticEventHandler.KNOCKBACK_THAT_BASTARD.remove(living);
									}
								}
							}

							return true;
						}
					}
				}
			} else if (useItem.getItem() instanceof EldritchPan) {
				Entity projectile = source.getDirectEntity();

				if (!(projectile instanceof Projectile))
					return false;

				if (!source.is(DamageTypeTags.BYPASSES_SHIELD)) {
					Vec3 sourcePos = source.getSourcePosition();

					if (sourcePos != null) {
						Vec3 lookVec = blocker.getViewVector(1.0F);
						Vec3 sourceToSelf = sourcePos.vectorTo(blocker.position()).normalize();
						sourceToSelf = new Vec3(sourceToSelf.x, 0.0D, sourceToSelf.z);

						if (sourceToSelf.dot(lookVec) < 0.0D) {
							projectile.kill();

							FoodData data = player.getFoodData();
							data.eat(4, 0.5F);

							player.level().playSound(null, player.getX(), player.getY(), player.getZ(),
									SoundEvents.PLAYER_BURP, SoundSource.PLAYERS, 0.5F,
									player.level().random.nextFloat() * 0.1F + 0.9F);

							player.gameEvent(GameEvent.EAT);

							if (projectile instanceof LargeFireball fireball) {
								fireball.explosionPower = 0;
							}

							if (player.level() instanceof ServerLevel level) {
								Vec3 angle = player.getLookAngle();
								angle.multiply(1, 0, 1).normalize().multiply(0.5, 0.5, 0.5);

								level.sendParticles(new ItemParticleOption(ParticleTypes.ITEM,
										new ItemStack(Items.FIRE_CHARGE)), player.getX() + angle.x,
										player.getY() + player.getEyeHeight() - 0.1, player.getZ() + angle.z,
										10, 0.3D, 0.3D, 0.3D, 0.03D);
							}

							return true;
						}
					}
				}
			}
		}

		return false;
	}

@Inject(method = "isDamageSourceBlocked", at = @At("HEAD"), cancellable = true)
	private void onDamageSourceBlocking(DamageSource source, CallbackInfoReturnable<Boolean> info) {
		if (SuperpositionHandler.onDamageSourceBlocking(((LivingEntity)(Object)this), this.useItem, source, info)) {
			info.setReturnValue(true);
		}
	}

@Override
	public boolean isActuallyReallyBlocking() {
		if (this.isUsingItem() && !this.useItem.isEmpty()) {
			Item item = this.useItem.getItem();
			if (item.getUseAnimation(this.useItem) != UseAnim.BLOCK)
				return false;
			else
				return item.getUseDuration(this.useItem) - this.useItemRemaining >= 0; // 0 for no warm-up time
		} else
			return false;
	}

public void breakShield(LivingEntity entity, boolean expired) {
		// Temp shields should break first before permanent ones. Reset time each time a temp shield is busted.
		if (this.temporaryShields > 0) {
			this.temporaryShields--;
			this.resetTimer();
		} else if (this.permanentShields > 0) {
			this.permanentShields--;
		}

		if (entity instanceof ServerPlayer player && !expired) {
			player.awardStat(TFStats.TF_SHIELDS_BROKEN.get());
		}
		entity.level().playSound(null, entity.blockPosition(), expired ? TFSounds.SHIELD_EXPIRE.get() : TFSounds.SHIELD_BREAK.get(), SoundSource.PLAYERS, 1.0F, (entity.getRandom().nextFloat() - entity.getRandom().nextFloat()) * 0.3F + 1.0F);
		entity.setData(TFDataAttachments.FORTIFICATION_SHIELDS, this);
	}

public void tick(LivingEntity entity) {
		if (this.temporaryShieldsLeft() > 0 && !(entity instanceof Player player && player.getAbilities().invulnerable)) {
			if (this.timer <= 0) {
				this.breakShield(entity, true);
			} else if (this.checkLichCrownBonus(entity)) {
				// Timer decay skipped after every 2 ticks so that shields last 50% longer with Lich Crown worn
				this.timer--;
			}
		}
	}

private boolean checkLichCrownBonus(LivingEntity entity) {
		//return entity.getItemBySlot(EquipmentSlot.HEAD).is(TFItems.LICH_CROWN) ? (entity.tickCount % 3) != 0 : true;
		// Simplified but same logic as the line above
		return !entity.getItemBySlot(EquipmentSlot.HEAD).is(TFItems.MYSTIC_CROWN) || (entity.tickCount % 3) != 0;
	}

public void setShields(LivingEntity entity, int amount, boolean temp) {
		if (temp) {
			this.temporaryShields = Math.clamp(amount, 0, 115);
			this.resetTimer();
		} else {
			this.permanentShields = Math.clamp(amount, 0, 115);
		}
		entity.setData(TFDataAttachments.FORTIFICATION_SHIELDS, this);
	}

public void addShields(LivingEntity entity, int amount, boolean temp) {
		if (temp) {
			if (this.temporaryShields <= 0) {
				this.resetTimer(); // Since we add new shields to the stack instead of setting them, no timer reset is needed, unless they start from 0 shields.
			}

			this.temporaryShields = Math.clamp(this.temporaryShields + amount, 0, 115);
		} else {
			this.permanentShields = Math.clamp(this.permanentShields + amount, 0, 115);
		}
		entity.setData(TFDataAttachments.FORTIFICATION_SHIELDS, this);
	}

public static void addShieldBreakParticles(DamageSource src, LivingEntity entity) {
		ParticlePacket particlePacket = new ParticlePacket();

		Vec3 pos = src.getSourcePosition();
		if (src.getDirectEntity() instanceof LivingEntity living) pos = living.getEyePosition(); // If entity is not null, transfer the position to the eye level
		if (src.getEntity() instanceof TraceableEntity traceable && traceable.getOwner() instanceof LivingEntity living) pos = living.getEyePosition(); // If entity is not null, transfer the position to the eye level

		if (pos != null) {
			Vec3 lichPos = entity.position().add(0.0D, entity.getBbHeight() * 0.65D, 0.0D);
			Vec3 offset = pos.subtract(lichPos).multiply(1.0D, 0.0D, 1.0D).normalize();
			pos = lichPos.add(offset.scale(0.55D));

			double sizeRange = 0.85D; // Change this value to change size of the plane in which the particle may be placed

			for (int j = 0; j < 16; ++j) {
				double horizontal = entity.getRandom().nextDouble() - 0.5D;
				double x = sizeRange * offset.z * horizontal;
				double y = sizeRange * (entity.getRandom().nextDouble() - 0.5D);
				double z = sizeRange * offset.x * -horizontal;
				particlePacket.queueParticle(TFParticleType.SHIELD_BREAK.get(), false, false, pos.x + x, pos.y + y, pos.z + z, x * 0.5D, y * 0.5D, z * 0.5D);
			}
		} else {
			pos = entity.position().add(0.0D, entity.getBbHeight() * 0.65D, 0.0D);
			for (int j = 0; j < 16; ++j) {
				double x = (entity.getRandom().nextDouble() - 0.5D);
				double y = (entity.getRandom().nextDouble() - 0.5D) * 0.25D;
				double z = (entity.getRandom().nextDouble() - 0.5D);
				particlePacket.queueParticle(TFParticleType.SHIELD_BREAK.get(), false, false, pos.x + x, pos.y + y, pos.z + z, x * 0.33D, y * 0.33D, z * 0.33D);
			}
		}

		PacketDistributor.sendToPlayersTrackingEntity(entity, particlePacket);
		if (entity instanceof ServerPlayer player) PacketDistributor.sendToPlayer(player, particlePacket);
	}

private void resetTimer() {
		this.timer = 240;
	}

@Override
	public InteractionResult performScepterAction(Level level, ItemStack stack, Player player, InteractionHand hand) {
		if (!level.isClientSide()) {
			player.getData(TFDataAttachments.FORTIFICATION_SHIELDS).setShields(player, 5, true);
			if (!player.isCreative()) {
				stack.hurtWithoutBreaking(1, player);
			}
		}
		player.playSound(TFSounds.SHIELD_ADD.get(), 1.0F, (player.getRandom().nextFloat() - player.getRandom().nextFloat()) * 0.2F + 1.0F);

		if (!player.isCreative()) {
			player.getCooldowns().addCooldown(stack, 1200);
		}
		return InteractionResult.SUCCESS;
	}

private void updateShields(EntityTickEvent.Post event) {
		if (event.getEntity() instanceof LivingEntity living && !living.level().isClientSide() && living.hasData(TFDataAttachments.FORTIFICATION_SHIELDS)) {
			event.getEntity().getData(TFDataAttachments.FORTIFICATION_SHIELDS).tick(living);
		}
	}

private void absorbShieldHits(LivingIncomingDamageEvent event) {
		LivingEntity living = event.getEntity();
		// shields
		if (!living.level().isClientSide() && !event.getSource().is(DamageTypeTags.BYPASSES_ARMOR)) {
            FortificationShieldAttachment attachment = living.getData(TFDataAttachments.FORTIFICATION_SHIELDS);
			if (attachment.shieldsLeft() > 0) {
				if (living.invulnerableTime <= 0) {
					attachment.breakShield(living, false);
					FortificationShieldAttachment.addShieldBreakParticles(event.getSource(), living);
					living.invulnerableTime = 20; //invulnerableDuration was only a static constant.
				}
				event.setCanceled(true);
			}
		}
	}
